import React from "react";
import { useParams, useNavigate } from "react-router-dom";

const jobData = {
  1:{title:"Frontend Developer",role:"React.js Developer",description:"Build responsive UI components, collaborate with backend.",responsibilities:"Develop UI components, Optimize performance, Write tests.",skills:"React, JS, HTML, CSS",experience:"2-4 years",qualifications:"B.Tech in CS",ctc:"8-12 LPA"},
  2:{title:"Backend Engineer",role:"Node.js Developer",description:"Design scalable APIs and manage databases.",responsibilities:"Develop REST APIs, Database design, Maintain code quality.",skills:"Node.js, Express, MongoDB",experience:"3-5 years",qualifications:"B.Tech/M.Tech in CS",ctc:"10-15 LPA"},
  3:{title:"UI/UX Designer",role:"Product Designer",description:"Design UI and improve UX for web apps.",responsibilities:"Create wireframes, Prototypes, User testing.",skills:"Figma, Adobe XD",experience:"1-3 years",qualifications:"Design Degree",ctc:"6-10 LPA"},
  4:{title:"Full Stack Developer",role:"MERN Developer",description:"Build full stack web apps.",responsibilities:"Frontend + Backend development, APIs.",skills:"MongoDB, Express, React, Node",experience:"3-5 years",qualifications:"B.Tech in CS",ctc:"10-15 LPA"},
  5:{title:"Data Analyst",role:"Business Analyst",description:"Analyze business data and create reports.",responsibilities:"Data cleaning, Reporting, Tableau dashboards.",skills:"Excel, SQL, Tableau",experience:"2-4 years",qualifications:"B.Sc in Statistics",ctc:"5-8 LPA"},
  6:{title:"DevOps Engineer",role:"Cloud Engineer",description:"Manage CI/CD pipelines.",responsibilities:"Automation, Cloud deployment, Monitoring.",skills:"AWS, Docker, Jenkins",experience:"3-6 years",qualifications:"B.Tech in CS",ctc:"12-18 LPA"},
  7:{title:"Mobile Developer",role:"Flutter Developer",description:"Build mobile apps.",responsibilities:"App development, UI integration, Testing.",skills:"Flutter, Dart",experience:"2-4 years",qualifications:"B.Tech in CS",ctc:"8-12 LPA"},
  8:{title:"QA Engineer",role:"Automation Tester",description:"Test and automate test cases.",responsibilities:"Test scripts, Regression testing, Automation.",skills:"Selenium, Java",experience:"2-5 years",qualifications:"B.Tech in CS",ctc:"6-10 LPA"},
  9:{title:"Marketing Executive",role:"Digital Marketer",description:"Plan and execute marketing campaigns.",responsibilities:"SEO, Social media, Paid ads.",skills:"SEO, Social Media, Ads",experience:"1-3 years",qualifications:"MBA Marketing",ctc:"4-8 LPA"},
  10:{title:"HR Executive",role:"HR Associate",description:"Manage recruitment and employee relations.",responsibilities:"Hiring, Payroll, HRMS.",skills:"Recruitment, Payroll, HRMS",experience:"1-3 years",qualifications:"MBA HR",ctc:"4-8 LPA"},
};

export default function JobDetails() {
  const { id } = useParams();
  const navigate = useNavigate();
  const job = jobData[id];
  if(!job) return <p>Job not found</p>;

  return (
    <div className="job-details-container">
      <div style={{display:"flex", justifyContent:"space-between", alignItems:"flex-start"}}>
        <div>
          <h2>{job.title}</h2>
          <h4>{job.role}</h4>
        </div>
        <button className="apply-btn" onClick={()=>navigate(`/apply/${id}`)}>Apply Now</button>
      </div>
      <hr style={{margin:"20px 0"}}/>
      <p><strong>Job Description:</strong> {job.description}</p>
      <p><strong>Key Responsibilities:</strong> {job.responsibilities}</p>
      <p><strong>Skill Set Required:</strong> {job.skills}</p>
      <p><strong>Experience Required:</strong> {job.experience}</p>
      <p><strong>Qualification Details:</strong> {job.qualifications}</p>
      <p><strong>CTC:</strong> {job.ctc}</p>
    </div>
  );
}
